import csv
from pathlib import Path


def read_points(path="input/points.csv"):
    with open(path, encoding="ascii", newline="") as handle:
        records = list(csv.reader(handle))
    return [
        {"id": row[0], "x": float(row[1]), "y": float(row[2])}
        for row in records[1:]
    ]


def read_initial(path="input/init.txt"):
    text = Path(path).read_text(encoding="ascii")
    result = {}
    for block in text.strip().split("\n\n"):
        rows = block.splitlines()
        k = int(rows[0].split(" ")[1])
        weights = [float(x) for x in rows[1].split(" ")[1:]]
        means = []
        covariances = []
        for row in rows[2:]:
            _, index, x, y, a, b, c = row.split(" ")
            means.append((float(x), float(y)))
            covariances.append((float(a), float(b), float(c)))
        result[k] = {
            "weights": weights, "means": means,
            "covariances": covariances,
        }
    return result


def read_parameters(path="input/params.txt"):
    lines = [
        line.split(" ") for line in
        Path(path).read_text(encoding="ascii").splitlines()
    ]
    raw = {line[0]: line[1:] for line in lines}
    return {
        "ks": list(map(int, raw["K"])),
        "iterations": int(raw["ITERATIONS"][0]),
        "types": raw["TYPES"],
        "epsilon": float(raw["REGULARIZATION"][0]),
        "settle": float(raw["SETTLE_TOLERANCE"][0]),
        "kmeans_iterations": int(raw["KMEANS_MAX_ITERATIONS"][0]),
        "cv_folds": int(raw["CV_FOLDS"][0]),
        "uncertain": float(raw["UNCERTAIN_THRESHOLD"][0]),
        "low_density": float(raw["LOW_DENSITY_THRESHOLD"][0]),
        "gof_edges": list(map(float, raw["GOF_EDGES"])),
        "map_x": tuple(map(float, raw["MAP_X"])),
        "map_y": tuple(map(float, raw["MAP_Y"])),
        "map_size": tuple(map(int, raw["MAP_SIZE"])),
    }


def read_all():
    return read_points(), read_initial(), read_parameters()

import math

from gaussian import weighted_log_density


def point_xy(point):
    return point["x"], point["y"]


def covariance_type_adjust(initial, type_name):
    weights = list(initial["weights"])
    means = list(initial["means"])
    source = list(initial["covariances"])
    if type_name == "FULL":
        covariance = source
    elif type_name == "DIAG":
        covariance = [(a, 0.0, c) for a, b, c in source]
    elif type_name == "SPHERICAL":
        covariance = [((a + c) / 2, 0.0, (a + c) / 2)
                      for a, b, c in source]
    else:
        shared = tuple(
            sum(weights[i] * source[i][column] for i in range(len(weights)))
            for column in range(3)
        )
        covariance = [shared for _ in weights]
    return {
        "weights": weights, "means": means, "covariances": covariance,
        "type": type_name,
    }


def responsibilities(points, model):
    count = len(model["weights"])
    records = []
    loglik = 0.0
    for point in points:
        coordinates = point_xy(point)
        scores = [
            weighted_log_density(
                coordinates, model["weights"][k], model["means"][k],
                model["covariances"][k],
            ) for k in range(count)
        ]
        maximum = max(scores)
        exponentials = [math.exp(score - maximum) for score in scores]
        normalizer = sum(exponentials)
        normalized = [value / normalizer for value in exponentials]
        log_density = maximum + math.log(normalizer)
        records.append({
            "responsibilities": normalized,
            "log_density": log_density, "scores": scores,
        })
        loglik += log_density
    return records, loglik


def update_model(points, records, type_name, regularization):
    n = len(points)
    k_count = len(records[0]["responsibilities"])
    weighted_counts = [
        sum(row["responsibilities"][k] for row in records)
        for k in range(k_count)
    ]
    weights = [weight / n for weight in weighted_counts]
    means = []
    for k, nk in enumerate(weighted_counts):
        x = sum(
            row["responsibilities"][k] * point["x"]
            for point, row in zip(points, records)
        ) / nk
        y = sum(
            row["responsibilities"][k] * point["y"]
            for point, row in zip(points, records)
        ) / nk
        means.append((x, y))
    scatter = []
    for k, (mx, my) in enumerate(means):
        a = b = c = 0.0
        for point, record in zip(points, records):
            weight = record["responsibilities"][k]
            dx, dy = point["x"] - mx, point["y"] - my
            a += weight * dx * dx
            b += weight * dx * dy
            c += weight * dy * dy
        scatter.append((a, b, c))
    covariance = []
    if type_name == "TIED":
        shared = tuple(
            sum(row[column] for row in scatter) / n
            + (regularization if column in (0, 2) else 0.0)
            for column in range(3)
        )
        covariance = [shared] * k_count
    else:
        for k, (a, b, c) in enumerate(scatter):
            count = weighted_counts[k]
            if type_name == "FULL":
                covariance.append(
                    (a / count + regularization, b / count,
                     c / count + regularization)
                )
            elif type_name == "DIAG":
                covariance.append(
                    (a / count + regularization, 0.0,
                     c / count + regularization)
                )
            else:
                variance = (a / count + c / count) / 2 + regularization
                covariance.append((variance, 0.0, variance))
    return {
        "weights": weights, "means": means,
        "covariances": covariance, "type": type_name,
    }


def run_em(points, initial, type_name, iterations, epsilon, tolerance):
    model = covariance_type_adjust(initial, type_name)
    records, loglik = responsibilities(points, model)
    trace = [loglik]
    for _ in range(iterations):
        model = update_model(points, records, type_name, epsilon)
        records, loglik = responsibilities(points, model)
        trace.append(loglik)
    end = trace[-1]
    settled_at = next(
        t for t in range(len(trace))
        if all(abs(value - end) <= tolerance for value in trace[t:])
    )
    increases = [trace[t] - trace[t - 1] for t in range(1, len(trace))]
    largest_t = max(range(1, len(trace)),
                    key=lambda t: (increases[t - 1], -t))
    violations = [
        t for t in range(1, len(trace))
        if trace[t] < trace[t - 1] - 0.000001 * abs(trace[t - 1])
    ]
    return {
        "model": model, "records": records,
        "trace": trace, "loglik": end,
        "settled_at": settled_at,
        "largest_increase": (largest_t, increases[largest_t - 1]),
        "violations": violations,
    }

import math


PI = math.pi


def determinant(cov):
    a, b, c = cov
    return a * c - b * b


def mahalanobis(point, mean, cov):
    x, y = point
    dx, dy = x - mean[0], y - mean[1]
    a, b, c = cov
    return (c * dx * dx - 2 * b * dx * dy + a * dy * dy) / determinant(cov)


def weighted_log_density(point, weight, mean, covariance):
    return (
        math.log(weight) - math.log(2 * PI)
        - math.log(determinant(covariance)) / 2
        - mahalanobis(point, mean, covariance) / 2
    )


def eigen_data(covariance):
    a, b, c = covariance
    center = (a + c) / 2
    delta = math.sqrt(((a - c) / 2) ** 2 + b * b)
    leading, trailing = center + delta, center - delta
    if b == 0:
        direction = (1.0, 0.0) if a >= c else (0.0, 1.0)
    else:
        vx, vy = ((leading - c, b) if a >= c else (b, leading - a))
        length = math.sqrt(vx * vx + vy * vy)
        direction = (
            (vx / length, vy / length) if vx >= 0
            else (-vx / length, -vy / length)
        )
    theta = math.atan2(direction[1], direction[0]) * 180 / PI
    return {
        "leading": leading,
        "trailing": trailing,
        "direction": direction,
        "angle": theta,
        "axes": (math.sqrt(leading), math.sqrt(trailing)),
        "area": PI * math.sqrt(leading * trailing),
        "correlation": b / math.sqrt(a * c),
    }


def bhattacharyya(mean_a, cov_a, mean_b, cov_b):
    mean_cov = tuple((x + y) / 2 for x, y in zip(cov_a, cov_b))
    distance = (
        mahalanobis(mean_b, mean_a, mean_cov) / 8
        + math.log(determinant(mean_cov)
                   / math.sqrt(determinant(cov_a) * determinant(cov_b))) / 2
    )
    return distance, math.exp(-distance)

def distance2(point, mean):
    dx = point["x"] - mean[0]
    dy = point["y"] - mean[1]
    return dx * dx + dy * dy


def distance(a, b):
    dx, dy = a[0] - b[0], a[1] - b[1]
    return (dx * dx + dy * dy) ** 0.5


def assignments(points, centers):
    return [
        min(range(len(centers)), key=lambda k: (
            distance2(point, centers[k]), k
        )) + 1 for point in points
    ]


def run_kmeans(points, initial_centers, max_iterations):
    centers = list(initial_centers)
    assigned = assignments(points, centers)
    iterations = 0
    for t in range(1, max_iterations + 1):
        new_centers = []
        for k in range(1, len(centers) + 1):
            members = [point for point, cluster in zip(points, assigned)
                       if cluster == k]
            if not members:
                new_centers.append(centers[k - 1])
            else:
                new_centers.append((
                    sum(point["x"] for point in members) / len(members),
                    sum(point["y"] for point in members) / len(members),
                ))
        centers = new_centers
        new_assignment = assignments(points, centers)
        iterations = t
        if new_assignment == assigned:
            assigned = new_assignment
            break
        assigned = new_assignment
    inertia = sum(
        distance2(point, centers[cluster - 1])
        for point, cluster in zip(points, assigned)
    )
    return {
        "centers": centers, "assignment": assigned,
        "iterations": iterations, "inertia": inertia,
        "sizes": [assigned.count(k) for k in range(1, len(centers) + 1)],
    }

from pathlib import Path


LEVELS = " .:-=+*#%@"


def dec(value, places=4):
    result = f"{value:.{places}f}"
    return result[1:] if result.startswith("-") and float(result) == 0 else result


def optional(value):
    return "-" if value is None else dec(value)


def values(items):
    return " ".join(str(v) if isinstance(v, int) else dec(v) for v in items)


def framed(grid):
    if not grid:
        return []
    border = "+" + "-" * len(grid[0]) + "+"
    return [border] + ["|" + "".join(line) + "|" for line in grid] + [border]


def write_lines(name, lines):
    target = Path("output") / name
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text("\n".join(lines) + "\n", encoding="ascii")


def write_blocks(name, blocks):
    rows = []
    for index, block in enumerate(blocks):
        if index:
            rows.append("")
        rows.extend(block)
    write_lines(name, rows)
